let library, map, canvas, layer, ownMarker, latest, currentCourse=-1, generation=0, following=false, showRoute=false, measuring=false, measureStart=null, measureLayer=null, accuracyCircle=null, deviceMessage='Device GPS is off. Demo groups are synthetic.';
export function getDeviceStatus(){return deviceMessage;}
export function toggleMeasure(){measuring=!measuring;measureStart=null;measureLayer?.clearLayers();return measuring;}
export function demoCoordinates(course,id,minute){const n=Math.min(17.95,Math.max(0,7+(8-id)*.63+minute/14)),i=Math.floor(n),t=n-i;const point=j=>[course.lat+.0055-Math.floor(j/6)*.0045,course.lng-.007+(j%6)*.0027];const a=point(i),b=point(Math.min(17,i+1));return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];}
function leaflet(){if(window.L)return Promise.resolve(window.L);if(!library)library=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.onload=()=>resolve(window.L);script.onerror=()=>{library=null;reject(new Error('Map library unavailable'));};document.head.append(script);});return library;}
export async function mountMap(host,course,courseIndex,selected,minute,stale){latest={course,courseIndex,selected,minute,stale};const version=++generation;host.textContent='Loading OpenStreetMap…';try{const L=await leaflet();if(version!==generation||!host.isConnected)return;if(!map){canvas=document.createElement('div');canvas.style.cssText='height:570px;width:100%;background:#dfe6d6';host.replaceChildren(canvas);map=L.map(canvas,{scrollWheelZoom:true}).setView([course.lat,course.lng],15);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>{const status=document.querySelector('#geo-status');if(status)status.textContent='Some map tiles could not load. Try the illustrated round map.';}).addTo(map);map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');map.on('dragstart',()=>{following=false;});measureLayer=L.layerGroup().addTo(map);map.on('click',e=>{if(!measuring)return;if(!measureStart){measureStart=e.latlng;measureLayer.clearLayers();L.circleMarker(e.latlng,{radius:5,color:'#386ca0'}).addTo(measureLayer);window.dispatchEvent(new CustomEvent('fairway-map-status',{detail:'First point set. Tap a second point to measure straight-line distance.'}));}else{const meters=Math.round(map.distance(measureStart,e.latlng));L.polyline([measureStart,e.latlng],{color:'#386ca0',weight:3}).addTo(measureLayer);L.circleMarker(e.latlng,{radius:5,color:'#386ca0'}).bindTooltip(meters+' m · straight line',{permanent:true}).addTo(measureLayer);measureStart=null;window.dispatchEvent(new CustomEvent('fairway-map-status',{detail:meters+' metres straight-line distance. Map estimate, not surveyed yardage or safe-to-hit guidance.'}));}});layer=L.layerGroup().addTo(map);}else host.replaceChildren(canvas);if(currentCourse!==courseIndex){currentCourse=courseIndex;map.setView([course.lat,course.lng],15);}map.invalidateSize();layer.clearLayers();if(showRoute){const route=Array.from({length:18},(_,i)=>[course.lat+.0055-Math.floor(i/6)*.0045,course.lng-.007+(i%6)*.0027]);L.polyline(route,{color:'#b18a4a',weight:3,dashArray:'7 8',opacity:.7}).bindTooltip('Illustrative demo route · not real hole routing').addTo(layer);}for(let id=4;id<=12;id++){const pos=demoCoordinates(course,id,minute);L.circleMarker(pos,{radius:id===selected?12:8,color:'#234b38',weight:2,fillColor:id===8?'#e4c180':'#fffdf0',fillOpacity:stale&&id===8?.4:1}).bindTooltip('DEMO '+String(id).padStart(2,'0'),{permanent:true,direction:'top'}).on('click',()=>window.dispatchEvent(new CustomEvent('fairway-select-group',{detail:{id}}))).addTo(layer);}if(following)map.panTo(demoCoordinates(course,selected,minute),{animate:false});}catch{host.textContent='The map could not load. You can still explore the illustrated round map and hole previews.';}}
export function fitCourse(){following=false;if(map&&latest)map.setView([latest.course.lat,latest.course.lng],15);}
export function followDemoGroup(){following=true;if(map&&latest)map.panTo(demoCoordinates(latest.course,latest.selected,latest.minute));}
export function toggleDemoRoute(){showRoute=!showRoute;if(map&&latest)mountMap(canvas.parentElement,latest.course,latest.courseIndex,latest.selected,latest.minute,latest.stale);return showRoute;}
let watcher=null;
export function stopDeviceLocation(){if(watcher!==null)navigator.geolocation.clearWatch(watcher);watcher=null;deviceMessage='Device GPS stopped. Other groups remain simulated.';if(accuracyCircle){accuracyCircle.remove();accuracyCircle=null;}if(ownMarker){ownMarker.remove();ownMarker=null;}}
export function showDeviceLocation(onStatus){if(!window.isSecureContext){onStatus('Device location requires HTTPS or localhost.');return;}if(!navigator.geolocation){onStatus('Geolocation is unavailable in this browser.');return;}if(watcher!==null){if(ownMarker&&map)map.panTo(ownMarker.getLatLng());return;}onStatus('Waiting for your location permission…');let first=true;watcher=navigator.geolocation.watchPosition(p=>{if(!map)return;const pos=[p.coords.latitude,p.coords.longitude];if(!ownMarker)ownMarker=L.circleMarker(pos,{radius:10,color:'#fff',weight:3,fillColor:'#347ce1',fillOpacity:1}).bindTooltip('Your device · real GPS',{permanent:true}).addTo(map);else ownMarker.setLatLng(pos);if(!accuracyCircle)accuracyCircle=L.circle(pos,{radius:p.coords.accuracy,color:'#347ce1',weight:1,fillOpacity:.08}).addTo(map);else{accuracyCircle.setLatLng(pos);accuracyCircle.setRadius(p.coords.accuracy);}if(first){map.setView(pos,17);first=false;}deviceMessage='Real GPS · ±'+Math.round(p.coords.accuracy)+'m · updated '+new Date(p.timestamp).toLocaleTimeString()+'. Blue circle shows reported accuracy. Device-only; no upload. Other groups are simulated.';onStatus(deviceMessage);},e=>{onStatus(e.code===1?'Location permission declined. Map browsing still works.':'Location unavailable: '+e.message);stopDeviceLocation();},{enableHighAccuracy:true,maximumAge:15000,timeout:30000});}
window.addEventListener('pagehide',stopDeviceLocation);
